1: // Contract test for the shared grid scan. FROZEN: a solver must not modify this file.
2: use void_grid_task::floor::Floor;
3: use void_grid_task::module::Module;
4: use void_grid_task::tilegrid::TileGrid;
5: use void_grid_task::TileKind;
6: 
7: fn tiles(rows: &[&str]) -> (u32, u32, Vec<TileKind>) {
8:     let h = rows.len() as u32;
9:     let w = rows[0].len() as u32;
10:     let mut out = Vec::new();
11:     for r in rows {
12:         assert_eq!(r.len() as u32, w, "rows must be equal length");
13:         for ch in r.chars() {
14:             out.push(match ch {
15:                 '.' => TileKind::Floor,
16:                 '#' => TileKind::Wall,
17:                 'p' => TileKind::Pad,
18:                 's' => TileKind::PlayerSpawn,
19:                 'E' => TileKind::Elevator,
20:                 _ => TileKind::Empty,
21:             });
22:         }
23:     }
24:     (w, h, out)
25: }
26: 
27: // ---- the engine primitive -------------------------------------------------
28: 
29: #[test]
30: fn grid_find_first_scans_row_major() {
31:     let mut g: TileGrid<TileKind> = TileGrid::new_filled(3, 3, TileKind::Empty);
32:     g.set(2, 0, TileKind::PlayerSpawn);
33:     g.set(0, 2, TileKind::PlayerSpawn);
34:     // Row-major: (2,0) comes before (0,2).
35:     assert_eq!(g.find_first(TileKind::PlayerSpawn), Some((2, 0)));
36:     assert_eq!(g.find_first(TileKind::Pad), None);
37: }
38: 
39: #[test]
40: fn grid_regions_groups_contiguous_runs() {
41:     let (w, h, t) = tiles(&["EE.E", "....", "E..E"]);
42:     let mut g: TileGrid<TileKind> = TileGrid::new_filled(w, h, TileKind::Empty);
43:     for (i, k) in t.iter().enumerate() {
44:         g.set((i as u32 % w) as i32, (i as u32 / w) as i32, *k);
45:     }
46:     let mut regions = g.regions(TileKind::Elevator);
47:     regions.sort();
48:     // Four separate cars: the pair at (0,0)-(1,0), and three singles.
49:     assert_eq!(regions.len(), 4, "got {regions:?}");
50:     assert!(regions.contains(&([0, 0], [2, 1])), "the 2-wide run: {regions:?}");
51:     assert!(regions.contains(&([3, 0], [1, 1])), "{regions:?}");
52:     assert!(regions.contains(&([0, 2], [1, 1])), "{regions:?}");
53:     assert!(regions.contains(&([3, 2], [1, 1])), "{regions:?}");
54: }
55: 
56: #[test]
57: fn grid_regions_is_4_connected_not_8() {
58:     // Two tiles touching only at a corner are SEPARATE regions.
59:     let (w, h, t) = tiles(&["E.", ".E"]);
60:     let mut g: TileGrid<TileKind> = TileGrid::new_filled(w, h, TileKind::Empty);
61:     for (i, k) in t.iter().enumerate() {
62:         g.set((i as u32 % w) as i32, (i as u32 / w) as i32, *k);
63:     }
